const listFieldTaskUUIDs = `-- name: ListFieldTaskUUIDs :many
SELECT t.uuid
FROM operation_tasks t
JOIN branches b ON b.organization_id = t.organization_id AND b.id = t.branch_id
LEFT JOIN branches tb ON tb.organization_id = t.organization_id AND tb.id = t.to_branch_id
LEFT JOIN service_points sp ON sp.organization_id = t.organization_id AND sp.id = t.point_id
LEFT JOIN rentals r ON r.organization_id = t.organization_id AND r.id = t.rental_id
LEFT JOIN reservations res ON res.organization_id = t.organization_id AND res.id = t.reservation_id
LEFT JOIN vehicle_allocations va ON va.organization_id = res.organization_id AND va.id = res.allocation_id
LEFT JOIN vehicles v ON v.organization_id = t.organization_id AND v.id = COALESCE(t.vehicle_id, va.vehicle_id)
LEFT JOIN customers c ON c.organization_id = res.organization_id AND c.id = res.customer_id AND c.anonymized_at IS NULL
LEFT JOIN users au ON au.id = t.assignee_id
LEFT JOIN users cu ON cu.id = t.completed_by
LEFT JOIN vehicle_transfers vt ON vt.organization_id = t.organization_id AND vt.id = t.transfer_id
WHERE t.organization_id = $1
  AND b.organization_id = $1
  AND ($2::bigint[] IS NULL OR t.branch_id = ANY($2::bigint[])
       OR t.to_branch_id = ANY($2::bigint[]))
  AND ($3::text[] IS NULL OR t.status = ANY($3::text[]))
  AND ($4::text[] IS NULL OR t.task_type = ANY($4::text[]))
  AND ($5::uuid[] IS NULL OR b.uuid = ANY($5::uuid[]))
  AND ($6::uuid[] IS NULL OR au.uuid = ANY($6::uuid[])
       OR ($7::boolean IS TRUE AND t.assignee_id IS NULL))
  AND ($8::boolean IS NULL OR (t.assignee_id IS NULL) = $8::boolean)
  AND ($9::bigint IS NULL OR t.assignee_id = $9::bigint)
  AND ($10::text[] IS NULL OR t.location_kind = ANY($10::text[]))
  AND ($11::uuid[] IS NULL OR res.uuid = ANY($11::uuid[]))
  AND ($12::timestamptz IS NULL OR t.due_at >= $12::timestamptz)
  AND ($13::timestamptz IS NULL OR t.due_at < $13::timestamptz)
  AND (
    $14::text IS NULL
    OR r.reference ILIKE '%' || $14 || '%'
    OR res.reference ILIKE '%' || $14 || '%'
    OR v.plate ILIKE '%' || $14 || '%'
    OR t.address ILIKE '%' || $14 || '%'
    OR t.flight_number ILIKE '%' || $14 || '%'
    OR t.note ILIKE '%' || $14 || '%'
  )
ORDER BY t.due_at ASC, t.id ASC
LIMIT $15
`

type ListFieldTaskUUIDsParams struct {
	OrganizationID    int64              `json:"organization_id"`
	BranchIds         []int64            `json:"branch_ids"`
	Statuses          []string           `json:"statuses"`
	TaskTypes         []string           `json:"task_types"`
	BranchUuids       []uuid.UUID        `json:"branch_uuids"`
	AssigneeUuids     []uuid.UUID        `json:"assignee_uuids"`
	IncludeUnassigned pgtype.Bool        `json:"include_unassigned"`
	Unassigned        pgtype.Bool        `json:"unassigned"`
	AssigneeID        pgtype.Int8        `json:"assignee_id"`
	LocationKinds     []string           `json:"location_kinds"`
	ReservationUuids  []uuid.UUID        `json:"reservation_uuids"`
	DueFrom           pgtype.Timestamptz `json:"due_from"`
	DueTo             pgtype.Timestamptz `json:"due_to"`
	Q                 pgtype.Text        `json:"q"`
	LimitCount        int32              `json:"limit_count"`
}

// Bulk "all matching": the uuids of the filtered list (capped).
func (q *Queries) ListFieldTaskUUIDs(ctx context.Context, arg ListFieldTaskUUIDsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listFieldTaskUUIDs,
		arg.OrganizationID,
		arg.BranchIds,
		arg.Statuses,
		arg.TaskTypes,
		arg.BranchUuids,
		arg.AssigneeUuids,
		arg.IncludeUnassigned,
		arg.Unassigned,
		arg.AssigneeID,
		arg.LocationKinds,
		arg.ReservationUuids,
		arg.DueFrom,
		arg.DueTo,
		arg.Q,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var uuid uuid.UUID
		if err := rows.Scan(&uuid); err != nil {
			return nil, err
		}
		items = append(items, uuid)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listFieldTasks = `-- name: ListFieldTasks :many
SELECT t.id, t.uuid, t.task_type, t.status, t.origin, t.branch_id, t.due_at, t.planned_minutes, t.note,
    t.started_at, t.completed_at, t.completion_note, t.assigned_at, t.issue_note, t.issue_reported_at,
    t.location_kind, t.address, t.district, t.city, t.latitude, t.longitude,
    t.contact_name, t.contact_phone, t.flight_number, t.meeting_note, t.created_at, t.updated_at,
    t.rental_id, t.reservation_id, t.assignee_id, t.to_branch_id, t.transfer_id,
    b.uuid AS branch_uuid, b.code AS branch_code, b.name AS branch_name,
    tb.uuid AS to_branch_uuid, tb.code AS to_branch_code, tb.name AS to_branch_name,
    sp.uuid AS point_uuid, sp.name AS point_name, sp.type AS point_type,
    r.uuid AS rental_uuid, r.reference AS rental_reference, r.status AS rental_status,
    res.uuid AS reservation_uuid, res.reference AS reservation_reference, res.status AS reservation_status,
    res.starts_at AS reservation_starts_at, res.ends_at AS reservation_ends_at,
    v.uuid AS vehicle_uuid, v.plate AS vehicle_plate, v.id AS resolved_vehicle_id,
    au.uuid AS assignee_uuid, au.name AS assignee_name, au.surname AS assignee_surname, au.email AS assignee_email,
    cu.uuid AS completed_by_uuid, cu.name AS completed_by_name, cu.surname AS completed_by_surname, cu.email AS completed_by_email,
    vt.uuid AS transfer_uuid, vt.status AS transfer_status,
    COALESCE(NULLIF(c.company_title, ''), TRIM(c.first_name || ' ' || c.last_name), '')::text AS customer_name,
    COALESCE(c.phone, '')::text AS customer_phone,
    COUNT(*) OVER ()::bigint AS total
FROM operation_tasks t
JOIN branches b ON b.organization_id = t.organization_id AND b.id = t.branch_id
LEFT JOIN branches tb ON tb.organization_id = t.organization_id AND tb.id = t.to_branch_id
LEFT JOIN service_points sp ON sp.organization_id = t.organization_id AND sp.id = t.point_id
LEFT JOIN rentals r ON r.organization_id = t.organization_id AND r.id = t.rental_id
LEFT JOIN reservations res ON res.organization_id = t.organization_id AND res.id = t.reservation_id
LEFT JOIN vehicle_allocations va ON va.organization_id = res.organization_id AND va.id = res.allocation_id
LEFT JOIN vehicles v ON v.organization_id = t.organization_id AND v.id = COALESCE(t.vehicle_id, va.vehicle_id)
LEFT JOIN customers c ON c.organization_id = res.organization_id AND c.id = res.customer_id AND c.anonymized_at IS NULL
LEFT JOIN users au ON au.id = t.assignee_id
LEFT JOIN users cu ON cu.id = t.completed_by
LEFT JOIN vehicle_transfers vt ON vt.organization_id = t.organization_id AND vt.id = t.transfer_id
WHERE t.organization_id = $1
  AND b.organization_id = $1
  AND ($2::bigint[] IS NULL OR t.branch_id = ANY($2::bigint[])
       OR t.to_branch_id = ANY($2::bigint[]))
  AND ($3::text[] IS NULL OR t.status = ANY($3::text[]))
  AND ($4::text[] IS NULL OR t.task_type = ANY($4::text[]))
  AND ($5::uuid[] IS NULL OR b.uuid = ANY($5::uuid[]))
  AND ($6::uuid[] IS NULL OR au.uuid = ANY($6::uuid[])
       OR ($7::boolean IS TRUE AND t.assignee_id IS NULL))
  AND ($8::boolean IS NULL OR (t.assignee_id IS NULL) = $8::boolean)
  AND ($9::bigint IS NULL OR t.assignee_id = $9::bigint)
  AND ($10::text[] IS NULL OR t.location_kind = ANY($10::text[]))
  AND ($11::uuid[] IS NULL OR res.uuid = ANY($11::uuid[]))
  AND ($12::timestamptz IS NULL OR t.due_at >= $12::timestamptz)
  AND ($13::timestamptz IS NULL OR t.due_at < $13::timestamptz)
  AND (
    $14::text IS NULL
    OR r.reference ILIKE '%' || $14 || '%'
    OR res.reference ILIKE '%' || $14 || '%'
    OR v.plate ILIKE '%' || $14 || '%'
    OR t.address ILIKE '%' || $14 || '%'
    OR t.flight_number ILIKE '%' || $14 || '%'
    OR t.note ILIKE '%' || $14 || '%'
  )
ORDER BY
    CASE WHEN $15::text = 'due_at' AND NOT $16::boolean THEN t.due_at END ASC,
    CASE WHEN $15::text = 'due_at' AND $16::boolean THEN t.due_at END DESC,
    CASE WHEN $15::text = 'status' AND NOT $16::boolean THEN t.status END ASC,
    CASE WHEN $15::text = 'status' AND $16::boolean THEN t.status END DESC,
    CASE WHEN $15::text = 'task_type' AND NOT $16::boolean THEN t.task_type END ASC,
    CASE WHEN $15::text = 'task_type' AND $16::boolean THEN t.task_type END DESC,
    CASE WHEN $15::text = 'created_at' AND NOT $16::boolean THEN t.created_at END ASC,
    CASE WHEN $15::text = 'created_at' AND $16::boolean THEN t.created_at END DESC,
    t.due_at ASC, t.id DESC
LIMIT $18 OFFSET $17
`

